// 42-tap direct-form FIR, 8-bit samples, unpipelined MAC cone (the long
// register-to-register path -> lower Fmax; pipeline it to go faster).
module firr42_v5 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [7:0]  x,
    output reg  [15:0] y
);
    reg  [7:0]  xs [0:41];
    integer     i;
    reg  [23:0] acc;
    always @(*) acc = 8'd5 * xs[0] + 8'd12 * xs[1] + 8'd20 * xs[2] + 8'd28 * xs[3] + 8'd36 * xs[4] + 8'd44 * xs[5] + 8'd52 * xs[6] + 8'd60 * xs[7] + 8'd68 * xs[8] + 8'd76 * xs[9] + 8'd84 * xs[10] + 8'd92 * xs[11] + 8'd100 * xs[12] + 8'd108 * xs[13] + 8'd116 * xs[14] + 8'd124 * xs[15] + 8'd132 * xs[16] + 8'd140 * xs[17] + 8'd148 * xs[18] + 8'd156 * xs[19] + 8'd164 * xs[20] + 8'd172 * xs[21] + 8'd180 * xs[22] + 8'd188 * xs[23] + 8'd196 * xs[24] + 8'd204 * xs[25] + 8'd212 * xs[26] + 8'd220 * xs[27] + 8'd228 * xs[28] + 8'd236 * xs[29] + 8'd244 * xs[30] + 8'd252 * xs[31] + 8'd260 * xs[32] + 8'd268 * xs[33] + 8'd276 * xs[34] + 8'd284 * xs[35] + 8'd292 * xs[36] + 8'd300 * xs[37] + 8'd308 * xs[38] + 8'd316 * xs[39] + 8'd324 * xs[40] + 8'd332 * xs[41];
    always @(posedge clk) begin
        if (!rst_n) begin
            for (i = 0; i < 42; i = i + 1) xs[i] <= 8'd0;
            y <= 16'd0;
        end else begin
            xs[0] <= x;
            for (i = 1; i < 42; i = i + 1) xs[i] <= xs[i-1];
            y <= acc[15:0];
        end
    end
endmodule
